-- #987 wave 1 (pure additions): Dustwallow Marsh creature abilities, imported from DeltaTho PR 15 file 2026_10_24_42_world.sql.
-- 76 creatures, 152 smart_scripts rows. Only creatures that have NO source_type 0 rows today are written here;
-- scripts that would replace existing rows are wave 2. Filters/fixes: see (not shipped)
-- Idempotent: DELETE of the listed entries then INSERT. AIName is set to SmartAI only where AIName and ScriptName are empty.
-- Undo: DELETE FROM smart_scripts WHERE source_type=0 AND FIND_IN_SET(entryorguid, <entries below>); and
--   UPDATE creature_template SET AIName='' WHERE FIND_IN_SET(entry, <entries below>); (entries that already had AIName SmartAI: see backup in (not shipped).

SET @ENTRIES := '4323,4324,4329,4331,4339,4341,4343,4346,4347,4348,4356,4357,4361,4362,4363,4364,4366,4368,4370,4371,4374,4378,4379,4380,4385,4389,4390,4397,4401,4403,4404,4414,4834,4841,4922,4923,4966,4973,5057,5091,5092,5093,5094,5184,10036,10321,14230,14231,14233,14234,14235,14237,15552,16072,23589,23590,23591,23592,23594,23636,23637,23679,23687,23714,23841,23873,23899,23900,23941,23949,23951,24841,24842,38006,44390,51924';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `AIName` = '' AND `ScriptName` = '' AND FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
